PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','teacher','student')), name TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL, preferred_language TEXT NOT NULL DEFAULT 'az', whatsapp_phone TEXT, email TEXT, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('applicant','active','paused','graduated','withdrawn')), notes TEXT, is_demo INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS teachers (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, name TEXT NOT NULL, email TEXT, whatsapp_phone TEXT);
CREATE TABLE IF NOT EXISTS courses (id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, title TEXT NOT NULL, title_az TEXT, credits INTEGER DEFAULT 3);
CREATE TABLE IF NOT EXISTS sections (id INTEGER PRIMARY KEY, course_id INTEGER NOT NULL REFERENCES courses(id), teacher_id INTEGER REFERENCES teachers(id), term TEXT NOT NULL, schedule TEXT, room TEXT, capacity INTEGER NOT NULL DEFAULT 20);
CREATE TABLE IF NOT EXISTS enrollments (id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, section_id INTEGER NOT NULL REFERENCES sections(id) ON DELETE CASCADE, final_grade TEXT, UNIQUE(student_id, section_id));
CREATE TABLE IF NOT EXISTS class_sessions (id INTEGER PRIMARY KEY, section_id INTEGER NOT NULL REFERENCES sections(id) ON DELETE CASCADE, session_date TEXT NOT NULL, topic TEXT, UNIQUE(section_id, session_date));
CREATE TABLE IF NOT EXISTS attendance (id INTEGER PRIMARY KEY, session_id INTEGER NOT NULL REFERENCES class_sessions(id) ON DELETE CASCADE, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('present','late','absent','excused')), note TEXT, source TEXT DEFAULT 'manual', recorded_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_id, student_id));
CREATE TABLE IF NOT EXISTS grade_items (id INTEGER PRIMARY KEY, section_id INTEGER NOT NULL REFERENCES sections(id) ON DELETE CASCADE, title TEXT NOT NULL, max_points REAL NOT NULL DEFAULT 100, due_date TEXT, weight REAL DEFAULT 1);
CREATE TABLE IF NOT EXISTS grades (id INTEGER PRIMARY KEY, grade_item_id INTEGER NOT NULL REFERENCES grade_items(id) ON DELETE CASCADE, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, points REAL, comment TEXT, source TEXT DEFAULT 'manual', updated_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(grade_item_id, student_id));
CREATE TABLE IF NOT EXISTS assignments (id INTEGER PRIMARY KEY, section_id INTEGER NOT NULL REFERENCES sections(id) ON DELETE CASCADE, grade_item_id INTEGER REFERENCES grade_items(id) ON DELETE SET NULL, title_az TEXT NOT NULL, instructions_az TEXT, due_date TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS submissions (id INTEGER PRIMARY KEY, assignment_id INTEGER NOT NULL REFERENCES assignments(id) ON DELETE CASCADE, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, body TEXT NOT NULL, source TEXT DEFAULT 'web', status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','draft_ready','returned')), submitted_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(assignment_id, student_id));
CREATE TABLE IF NOT EXISTS corrections (id INTEGER PRIMARY KEY, submission_id INTEGER NOT NULL UNIQUE REFERENCES submissions(id) ON DELETE CASCADE, draft_az TEXT, final_az TEXT, is_sample INTEGER NOT NULL DEFAULT 0, drafted_by TEXT, approved_by INTEGER REFERENCES users(id), points REAL, approved_at TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS whatsapp_messages (id INTEGER PRIMARY KEY, wa_message_id TEXT UNIQUE, from_number TEXT NOT NULL, contact_name TEXT, body TEXT, received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, raw_json TEXT, student_id INTEGER REFERENCES students(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','applied','dismissed')), suggested_action TEXT, suggested_payload TEXT, handled_by INTEGER REFERENCES users(id), handled_at TEXT, is_demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS bot_runs (id INTEGER PRIMARY KEY, bot TEXT NOT NULL, ran_at TEXT DEFAULT CURRENT_TIMESTAMP, findings_json TEXT);
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY, user_id INTEGER, action TEXT, detail TEXT, at TEXT DEFAULT CURRENT_TIMESTAMP);
